use actix_web::{web,App,HttpResponse,HttpServer};use std::sync::Mutex;use fokus::{Board,Create};
async fn list(state:web::Data<Mutex<Board>>)->HttpResponse{HttpResponse::Ok().json(&state.lock().unwrap().tasks)}
async fn create(state:web::Data<Mutex<Board>>,input:web::Form<Create>)->HttpResponse{match state.lock().unwrap().create(input.into_inner()){Ok(t)=>HttpResponse::Created().json(t),Err(e)=>HttpResponse::BadRequest().json(serde_json::json!({"error":e}))}}
async fn toggle(state:web::Data<Mutex<Board>>,id:web::Path<u64>)->HttpResponse{if state.lock().unwrap().toggle(*id){HttpResponse::Ok().json(serde_json::json!({"updated":true}))}else{HttpResponse::NotFound().json(serde_json::json!({"error":"not found"}))}}
async fn remove(state:web::Data<Mutex<Board>>,id:web::Path<u64>)->HttpResponse{if state.lock().unwrap().delete(*id){HttpResponse::Ok().json(serde_json::json!({"deleted":true}))}else{HttpResponse::NotFound().json(serde_json::json!({"error":"not found"}))}}
#[actix_web::main]async fn main()->std::io::Result<()>{let state=web::Data::new(Mutex::new(Board::default()));HttpServer::new(move||App::new().app_data(state.clone()).route("/",web::get().to(||async{HttpResponse::Ok().content_type("text/html; charset=utf-8").body(include_str!("../index.html"))})).route("/health",web::get().to(||async{HttpResponse::Ok().json(serde_json::json!({"ok":true}))})).route("/api/tasks",web::get().to(list)).route("/api/tasks",web::post().to(create)).route("/api/tasks/{id}/toggle",web::post().to(toggle)).route("/api/tasks/{id}",web::delete().to(remove))).bind((std::env::var("HOST").unwrap_or("127.0.0.1".into()),std::env::var("PORT").unwrap_or("8080".into()).parse::<u16>().unwrap()))?.run().await}
